# ==================== safety ====================
"""Reply sanitising, fallbacks and the time governor. Nothing here may raise."""
import sys
import json
import time

OUT = sys.stdout            # the only channel to the engine
sys.stdout = sys.stderr     # stray prints can never reach the engine


def send(obj):
    OUT.write(json.dumps(obj, separators=(",", ":")) + "\n")
    OUT.flush()


def log(*a):
    try:
        print(*a, file=sys.stderr, flush=True)
    except Exception:
        pass


def fallback_action(req):
    legal = req.get("legal_actions") or []
    if "check" in legal:
        return {"type": "action", "action": "check"}
    if "call" in legal and (req.get("to_call") or 99) <= 2:
        return {"type": "action", "action": "call"}
    if "fold" in legal:
        return {"type": "action", "action": "fold"}
    return {"type": "action", "action": legal[0] if legal else "fold"}


def sanitize_action(reply, req):
    legal = req.get("legal_actions") or []
    a = reply.get("action") if isinstance(reply, dict) else None
    if a == "fold" and "check" in legal:
        a = "check"
    if a not in legal:
        return fallback_action(req)
    if a == "raise":
        try:
            lo, hi = int(req["min_raise"]), int(req["max_raise"])
            amt = int(round(float(reply.get("amount", lo))))
            return {"type": "action", "action": "raise", "amount": max(lo, min(hi, amt))}
        except Exception:
            return fallback_action(req)
    return {"type": "action", "action": a}


def fallback_discard(req):
    cards = req.get("hole_cards") or []
    try:
        board = req.get("board") or []
        ids3 = [CARD_ID[c] for c in cards]
        _, _, d = cheap_keep(ids3, [CARD_ID[c] for c in board[:3]])
        return {"type": "discard", "card": cards[ids3.index(d)]}
    except Exception:
        return {"type": "discard", "card": cards[0] if cards else "2c"}


def sanitize_discard(reply, req):
    cards = req.get("hole_cards") or []
    c = reply.get("card") if isinstance(reply, dict) else None
    if c in cards:
        return {"type": "discard", "card": c}
    return fallback_discard(req)


class Governor:
    """Chooses how much to compute from the time left per remaining hand."""
    FULL, HALF, QUARTER, PANIC = 0, 1, 2, 3

    def __init__(self):
        self.total_hands = 200
        self.max_reply_ms = 0.0
        self.mode_counts = [0, 0, 0, 0]
        self.t0 = 0.0

    def start(self, req, hand_id):
        self.t0 = time.perf_counter()
        left = req.get("time_left_ms")
        if left is None:
            mode = self.FULL
        else:
            per = left / max(1, self.total_hands - hand_id + 1)
            if left < 2000 or per < 25:
                mode = self.PANIC
            elif per < 50:
                mode = self.QUARTER
            elif per < 100:
                mode = self.HALF
            else:
                mode = self.FULL
        self.mode_counts[mode] += 1
        return mode

    def done(self):
        ms = (time.perf_counter() - self.t0) * 1000.0
        if ms > self.max_reply_ms:
            self.max_reply_ms = ms

# ==================== equity ====================
"""Equity against a (weighted) opponent range.

flop_equity   : sampled; scores all 3 of our keeps on the same samples
turn_equity   : exact over every opponent 2-card hand and every river card
river_equity  : exact over every opponent 2-card hand
All need numpy; scalar_equity is the slow fallback used without numpy.
Equity = P(win) + P(tie) / 2.
"""
import random
if HAVE_NP:
    import numpy as np
    _KEEP_IDX = ((0, 1), (0, 2), (1, 2))
    _PAIR_CACHE = {}

    def _pairs(k):
        """All index pairs (i < j) for k cards, cached."""
        p = _PAIR_CACHE.get(k)
        if p is None:
            i, j = np.triu_indices(k, 1)
            p = (i.astype(np.int64), j.astype(np.int64))
            _PAIR_CACHE[k] = p
        return p

    def flop_equity(hole3, flop3, n, rng, opp3=None):
        """Our 3 hole cards and the flop (card ids). Returns
        (eq, opp_key, win): eq = equity of keeps (0,1), (0,2), (1,2);
        opp_key (n,) = cheap key of the opponent's best keep on the flop (their
        flop strength, for filtering 'hands that continue'); win (3, n) = per
        sample result of each keep (1 win, 0.5 tie, 0 loss).
        opp3: optional (n, 3) array of sampled opponent hands (from a weighted
        range); default = uniform random hands."""
        dead = list(hole3) + list(flop3)
        rest = np.array([c for c in range(52) if c not in dead], dtype=np.int64)
        if opp3 is None:
            pick = rest[np.argsort(rng.random((n, rest.size)), axis=1)[:, :5]]
            opp, tr = pick[:, :3], pick[:, 3:]
        else:
            opp = opp3
            n = opp.shape[0]
            keys = rng.random((n, 52))
            keys[:, dead] = 9.0
            keys[np.arange(n)[:, None], opp] = 9.0
            tr = np.argpartition(keys, 2, axis=1)[:, :2].astype(np.int64)
        flop = np.tile(np.array(flop3, dtype=np.int64), (n, 1))
        okeep, _ = cheap_keep_batch(opp, flop)
        board = np.concatenate([flop, tr], axis=1)
        osc = eval_batch(np.concatenate([okeep, board], axis=1))
        opp_key = np.maximum.reduce([cheap_key_batch(np.concatenate([opp[:, [i, j]], flop], axis=1))
                                     for i, j in _KEEP_IDX])
        win = np.empty((3, n))
        for k, (i, j) in enumerate(_KEEP_IDX):
            mine = np.tile(np.array([hole3[i], hole3[j]], dtype=np.int64), (n, 1))
            msc = eval_batch(np.concatenate([mine, board], axis=1))
            win[k] = (msc > osc) + 0.5 * (msc == osc)
        return win.mean(1), opp_key, win

    def opp_hands(hole2, board, dead):
        """All opponent 2-card hands from the unseen cards. Returns (hands (M,2), unseen)."""
        seen = set(hole2) | set(board) | set(dead)
        unseen = np.array([c for c in range(52) if c not in seen], dtype=np.int64)
        i, j = _pairs(unseen.size)
        return np.stack([unseen[i], unseen[j]], axis=1), unseen

    def river_equity(hole2, board5, dead, weights=None):
        """Exact. Returns (equity, hands (M,2), opp_scores (M,), result (M,))."""
        hands, _ = opp_hands(hole2, board5, dead)
        m = hands.shape[0]
        b = np.tile(np.array(board5, dtype=np.int64), (m, 1))
        osc = eval_batch(np.concatenate([hands, b], axis=1))
        msc = eval7(list(hole2) + list(board5))
        res = (msc > osc) + 0.5 * (msc == osc)
        w = np.ones(m) if weights is None else weights
        return float((res * w).sum() / w.sum()), hands, osc, res

    def turn_equity(hole2, board4, dead, weights=None, river_step=1):
        """Exact over all opponent hands and river cards (river_step > 1 uses
        every n-th river card to save time). Returns
        (equity, hands (M,2), opp_now (M,), per_hand (M,)): opp_now = each hand's
        score on the turn board (6 cards); per_hand = our equity against each hand."""
        hands, unseen = opp_hands(hole2, board4, dead)
        m = hands.shape[0]
        rivers = unseen[::river_step]
        u = rivers.size
        b4 = np.array(board4, dtype=np.int64)
        ok = (hands[:, 0:1] != rivers[None, :]) & (hands[:, 1:2] != rivers[None, :])
        hi, ri = np.nonzero(ok)                      # only combos without a card clash
        rows = np.empty((hi.size, 7), dtype=np.int64)
        rows[:, 0:2] = hands[hi]
        rows[:, 2:6] = b4
        rows[:, 6] = rivers[ri]
        osc = eval_batch(rows)
        mine = np.empty((u, 7), dtype=np.int64)
        mine[:, 0:2] = np.array(hole2, dtype=np.int64)
        mine[:, 2:6] = b4
        mine[:, 6] = rivers
        msc = eval_batch(mine)[ri]
        res = (msc > osc) + 0.5 * (msc == osc)
        per_hand = np.bincount(hi, weights=res, minlength=m) / np.maximum(ok.sum(1), 1)
        opp_now = eval_batch(np.concatenate([hands, np.tile(b4, (m, 1))], axis=1))
        w = np.ones(m) if weights is None else weights
        return float((per_hand * w).sum() / w.sum()), hands, opp_now, per_hand

    def top_share_equity(result, strength, weights, share):
        """Equity against only the strongest `share` (by weight) of the range.
        result: our outcome vs each hand/sample; strength: opponent strength."""
        if share >= 0.999:
            return float((result * weights).sum() / weights.sum())
        order = np.argsort(-strength, kind="stable")
        w = weights[order]
        cum = np.cumsum(w)
        cut = share * cum[-1]
        k = int(np.searchsorted(cum, cut)) + 1
        k = max(1, min(k, w.size))
        return float((result[order][:k] * w[:k]).sum() / w[:k].sum())


def scalar_equity(hole, board, dead, n, rnd=random):
    """Fallback without numpy: plain Monte Carlo vs a uniform random hand.
    hole: our 2 or 3 cards; if 3 (flop, before the discard) both sides discard
    by the cheap rule. Returns the equity of the cheap-rule keep."""
    seen = set(hole) | set(board) | set(dead)
    deck = [c for c in range(52) if c not in seen]
    need = 5 - len(board)
    pre = len(hole) == 3
    if pre:
        a, b, _ = cheap_keep(hole, board[:3])
        mine = [a, b]
    else:
        mine = list(hole)
    tot = 0.0
    for _ in range(n):
        pick = rnd.sample(deck, (3 if pre else 2) + need)
        if pre:
            x, y, _ = cheap_keep(pick[:3], board[:3])
            opp, extra = [x, y], pick[3:]
        else:
            opp, extra = pick[:2], pick[2:]
        full = list(board) + extra
        m, o = eval7(mine + full), eval7(opp + full)
        tot += 1.0 if m > o else (0.5 if m == o else 0.0)
    return tot / max(1, n)

# ==================== strategy ====================
"""Decision logic. Baseline v1: table preflop, range-narrowed equity postflop,
value-heavy betting, simulated discard, minimal opponent statistics.
Later phases replace the narrowing heuristic with the Bayesian range model."""
import random
if HAVE_NP:
    import numpy as np

KEEPS = ((0, 1, 2), (0, 2, 1), (1, 2, 0))      # (keep, keep, discard) indices


def clamp(x, lo, hi):
    return lo if x < lo else hi if x > hi else x


class OppModel:
    """Per-leg statistics about the opponent (resets with the process)."""

    def __init__(self):
        self.hands = 0
        self.bets_faced = 0
        self.folds_to_bet = 0
        self.post_actions = 0
        self.post_aggr = 0
        self.big_pf = 0

    @staticmethod
    def _freq(k, n, prior):
        n0 = CFG["STAT_N0"]
        return (k + n0 * prior) / (n + n0)

    def fold_to_bet(self):
        return self._freq(self.folds_to_bet, self.bets_faced, 0.40)

    def aggression(self):
        return self._freq(self.post_aggr, self.post_actions, 0.30)

    def big_pf_freq(self):
        return self._freq(self.big_pf, self.hands, 0.02)

    def is_station(self):
        return self.bets_faced >= CFG["STATION_MIN"] and self.fold_to_bet() < CFG["STATION_FOLD"]

    def observe_hand(self, history):
        self.hands += 1
        street = None
        facing = False          # opponent is facing our postflop bet or raise
        big = False
        for e in history or []:
            st, who, act = e.get("street"), e.get("actor"), e.get("action")
            if st != street:
                street, facing = st, False
            if who == "me":
                facing = (act == "raise" and st != "preflop")
                continue
            if st == "preflop":
                if act == "raise" and (e.get("amount") or 0) >= 40:
                    big = True
                continue
            self.post_actions += 1
            if act == "raise":
                self.post_aggr += 1
            if facing:
                self.bets_faced += 1
                if act == "fold":
                    self.folds_to_bet += 1
            facing = False
        if big:
            self.big_pf += 1


def read_history(history, seat, opp):
    """Replay the hand so far. Returns (x, pf_raises): x = share of the
    opponent's range that their actions leave (strongest hands first)."""
    my_bet, opp_bet = (1, 2) if seat == "button" else (2, 1)
    pot = 3
    street = "preflop"
    x = 1.0
    pf_raises = 0
    for e in history or []:
        st, who, act = e.get("street"), e.get("actor"), e.get("action")
        if st != street:
            street, my_bet, opp_bet = st, 0, 0
        amt = e.get("amount")
        if who == "me":
            if act == "raise" and amt is not None:
                pot += amt - my_bet
                my_bet = amt
                if st == "preflop":
                    pf_raises += 1
            elif act == "call":
                amt = opp_bet if amt is None else amt
                pot += amt - my_bet
                my_bet = amt
            continue
        if act == "raise" and amt is not None:
            if st == "preflop":
                pf_raises += 1
                x *= (CFG["SHRINK_PF_RAISE"] if pf_raises == 1 else
                      CFG["SHRINK_PF_3BET"] if pf_raises == 2 else CFG["SHRINK_PF_4BET"])
            else:
                frac = (amt - my_bet) / max(1.0, pot + (my_bet - opp_bet))
                x *= (CFG["SHRINK_BET_SMALL"] if frac < 0.4 else CFG["SHRINK_BET_MED"] if frac < 0.8 else
                      CFG["SHRINK_BET_LARGE"] if frac < 1.3 else CFG["SHRINK_BET_OVER"])
                if my_bet > 0:
                    x *= CFG["SHRINK_RAISE_EXTRA"]
            pot += amt - opp_bet
            opp_bet = amt
        elif act == "call":
            amt = my_bet if amt is None else amt
            pot += amt - opp_bet
            opp_bet = amt
            if st != "preflop":
                x *= CFG["SHRINK_CALL"]
    # trust the narrowing less against opponents who bet a lot, more against passive ones
    k = clamp(1.6 - 2.0 * opp.aggression(), 0.3, 1.2)
    return max(CFG["SHRINK_FLOOR"], x ** k), pf_raises


class Brain:
    def __init__(self):
        self.gov = Governor()
        self.opp = OppModel()
        self.rng = np.random.default_rng() if HAVE_NP else None
        self.hand_id = 0
        self.seat = "button"
        self.hole = []              # card ids we currently hold (3, then 2)
        self.hole_str = []
        self.dead = []              # both discards once known
        self.cache = {}
        self.errors = 0
        self.notices = 0

    # ------------------------------------------------------------ observation
    def observe(self, msg):
        t = msg.get("type")
        if t == "init":
            self.gov.total_hands = int(msg.get("total_hands") or 200)
        elif t == "new_hand":
            self.hand_id = int(msg.get("hand_id") or self.hand_id + 1)
            self.seat = msg.get("seat") or "button"
            self.hole_str = list(msg.get("hole_cards") or [])
            self.hole = [CARD_ID[c] for c in self.hole_str]
            self.dead = []
            self.cache = {}
        elif t == "discard_result":
            self.hole_str = list(msg.get("hole_cards") or self.hole_str)
            self.hole = [CARD_ID[c] for c in self.hole_str]
            self.dead = [CARD_ID[c] for c in (msg.get("my_discard"), msg.get("opp_discard")) if c in CARD_ID]
        elif t == "hand_result":
            self.opp.observe_hand(msg.get("history"))
        elif t == "notice":
            self.notices += 1

    # ---------------------------------------------------------------- equity
    def _equity(self, req, mode, x):
        """Returns (e_all, top): top(share) = equity against the strongest
        `share` of the opponent's range. Also caches the flop keep choice."""
        board = [CARD_ID[c] for c in req.get("board") or []]
        street = len(board)
        if not HAVE_NP or mode == Governor.PANIC:
            e = scalar_equity(self.hole, board, self.dead, 40)
            return e, (lambda share: max(0.0, e - (1.0 - share) * 0.30))
        if street == 3 and len(self.hole) == 3:
            sim = self.cache.get("flop")
            if sim is None:
                n = CFG["MC_FLOP"] >> mode
                sim = flop_equity(self.hole, board, n, self.rng)
                self.cache["flop"] = sim
            eq, key, win = sim
            w = np.ones(key.size)
            by_keep = [top_share_equity(win[k], key, w, x) for k in range(3)]
            best = int(np.argmax(by_keep))
            self.cache["keep"] = best
            return float(eq[best]), (lambda share: top_share_equity(win[best], key, w, share))
        ck = "s%d" % street
        got = self.cache.get(ck)
        if got is None:
            if street == 4:
                step = (1, 2, 4)[mode]
                e, hands, strength, res = turn_equity(self.hole, board, self.dead, None, step)
            else:
                e, hands, strength, res = river_equity(self.hole, board, self.dead, None)
            got = (e, strength, res, np.ones(res.size))
            self.cache[ck] = got
        e, strength, res, w = got
        return e, (lambda share: top_share_equity(res, strength, w, share))

    # --------------------------------------------------------------- preflop
    def _preflop(self, req, pf_raises):
        legal = req["legal_actions"]
        q = preflop_q(*self.hole)
        to_call = req.get("to_call", 0)
        opp_bet = req.get("opp_bet", 0)
        can_raise = "raise" in legal
        hi = req.get("max_raise", 0)
        if to_call == 0:
            if can_raise and q <= CFG["PF_ISO_Q"]:
                return {"action": "raise", "amount": CFG["PF_ISO_SIZE"]}
            return {"action": "check"}
        if pf_raises == 0:
            if can_raise and q <= CFG["PF_OPEN_Q"]:
                return {"action": "raise", "amount": CFG["PF_OPEN_SIZE"]}
            return {"action": "call"}
        shove_q = clamp(CFG["PF_SHOVE_ADAPT"] * self.opp.big_pf_freq(), CFG["PF_CALL_Q_ALLIN"], CFG["PF_SHOVE_ADAPT"])
        if opp_bet <= 8:
            call_q = CFG["PF_CALL_Q_SMALL"]
        elif opp_bet <= 16:
            call_q = CFG["PF_CALL_Q_MED"]
        elif opp_bet <= 40:
            call_q = max(CFG["PF_CALL_Q_BIG"], shove_q)
        elif opp_bet <= 80:
            call_q = max(CFG["PF_CALL_Q_HUGE"], shove_q)
        else:
            call_q = shove_q
        if can_raise:
            if pf_raises == 1 and q <= CFG["PF_3BET_Q"]:
                return {"action": "raise", "amount": min(hi, 3 * opp_bet)}
            if pf_raises == 2 and q <= CFG["PF_4BET_Q"]:
                return {"action": "raise", "amount": min(hi, int(2.5 * opp_bet))}
            if pf_raises >= 3 and q <= CFG["PF_5BET_Q"]:
                return {"action": "raise", "amount": hi}
        if q <= call_q:
            return {"action": "call"}
        return {"action": "fold"}

    # -------------------------------------------------------------- postflop
    def _bet(self, req, frac, e_r):
        """Build a bet or raise of `frac` of the pot; None if not sensible."""
        lo, hi = req["min_raise"], req["max_raise"]
        amount = int(round(req.get("opp_bet", 0) + frac * (req["pot"] + req.get("to_call", 0))))
        if amount >= CFG["ALLIN_IF_STACK_USE"] * hi:
            if e_r >= CFG["STACK_OFF_EQ"]:
                amount = hi
            else:
                amount = int(0.45 * hi)
                if amount < lo:
                    return None
        return {"action": "raise", "amount": clamp(amount, lo, hi)}

    def _postflop(self, req, mode, x):
        legal = req["legal_actions"]
        e_all, top = self._equity(req, mode, x)
        u = CFG["UNCERTAINTY"]
        e_r = (1.0 - u) * top(x) + u * e_all
        if self.seat != "button":
            e_r -= CFG["OOP_PENALTY"]
        to_call = req.get("to_call", 0)
        pot = req["pot"]
        street = len(req.get("board") or [])
        can_raise = "raise" in legal
        station = self.opp.is_station()
        if to_call == 0:
            if can_raise:
                floor = CFG["SHRINK_FLOOR"]
                e_c = top(max(floor, x * (0.90 if station else CFG["CALLER_SHARE"])))
                if e_c >= (CFG["STATION_VALUE_MIN"] if station else CFG["VALUE_MIN"]):
                    big = station or e_c >= CFG["VALUE_BIG"]
                    b = self._bet(req, CFG["BET_BIG"] if big else CFG["BET_SMALL"], e_r)
                    if b:
                        return b
                elif e_r < CFG["BLUFF_MAX_EQ"] and not station:
                    p = (CFG["BLUFF_FLOP"], CFG["BLUFF_TURN"], CFG["BLUFF_RIVER"])[street - 3]
                    p *= clamp(self.opp.fold_to_bet() / 0.40, 0.0, 2.0)
                    if random.random() < p:
                        b = self._bet(req, CFG["BLUFF_SIZE"], 0.0)
                        if b:
                            return b
            return {"action": "check"}
        need = to_call / float(pot + to_call)
        big_call = to_call > 0.4 * max(1, req.get("my_stack", 200))
        margin = CFG["BIG_CALL_MARGIN"] if big_call else CFG["CALL_MARGIN"]
        if can_raise and e_r >= CFG["RAISE_VALUE"]:
            b = self._bet(req, CFG["BET_BIG"], e_r)
            if b:
                return b
        if e_r >= need + margin:
            return {"action": "call"}
        return {"action": "fold"}

    # ----------------------------------------------------------- entry points
    def decide(self, req):
        hid = int(req.get("hand_id") or self.hand_id)
        mode = self.gov.start(req, hid)
        if not self.hole:
            raise RuntimeError("no hole cards")
        x, pf_raises = read_history(req.get("history"), self.seat, self.opp)
        if req.get("street") == "preflop":
            r = self._preflop(req, pf_raises)
        else:
            r = self._postflop(req, mode, x)
        r["type"] = "action"
        return r

    def discard(self, req):
        hid = int(req.get("hand_id") or self.hand_id)
        mode = self.gov.start(req, hid)
        cards = list(req.get("hole_cards") or self.hole_str)
        ids3 = [CARD_ID[c] for c in cards]
        flop = [CARD_ID[c] for c in (req.get("board") or [])[:3]]
        if HAVE_NP and mode != Governor.PANIC:
            self.hole, self.hole_str = ids3, cards
            if "keep" not in self.cache:
                self._equity({"board": req.get("board")}, mode, 1.0)
            return {"type": "discard", "card": cards[KEEPS[self.cache["keep"]][2]]}
        _, _, d = cheap_keep(ids3, flop)
        return {"type": "discard", "card": cards[ids3.index(d)]}

# ==================== main ====================
"""Entry point: the safe message loop. One flushed JSON line per request."""
import sys
import json


def summary(brain, why):
    g = brain.gov
    log("SUMMARY %s hands=%d max_reply_ms=%.1f modes=%s errors=%d notices=%d fold_to_bet=%.2f aggr=%.2f" % (
        why, brain.hand_id, g.max_reply_ms, g.mode_counts, brain.errors, brain.notices,
        brain.opp.fold_to_bet(), brain.opp.aggression()))


def main():
    brain = Brain()
    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        if not isinstance(msg, dict):
            continue
        t = msg.get("type")
        if t == "action_request":
            try:
                reply = sanitize_action(brain.decide(msg), msg)
            except Exception as e:
                brain.errors += 1
                log("ERR action", repr(e))
                reply = fallback_action(msg)
            send(reply)
            brain.gov.done()
        elif t == "discard_request":
            try:
                reply = sanitize_discard(brain.discard(msg), msg)
            except Exception as e:
                brain.errors += 1
                log("ERR discard", repr(e))
                reply = fallback_discard(msg)
            send(reply)
            brain.gov.done()
        elif t == "match_end":
            break
        else:
            try:
                brain.observe(msg)
            except Exception as e:
                brain.errors += 1
                log("ERR observe", repr(e))
    summary(brain, "end")




if __name__ == "__main__":
    main()
